def write_blockmesh(NA, NW, NB, path="system/blockMeshDict"):
    d  = "FoamFile{version 2.0; format ascii; class dictionary; object blockMeshDict;}
scale 1;

vertices
(
"+vstr()+"
);

blocks
(
"
    for v,(a,b,c) in [(blocks[0][0],(NA,NW,1)),(blocks[1][0],(NB,NW,1)),(blocks[2][0],(NB,NW,1)),(blocks[3][0],(NA,NW,1))]:
        d += "    hex (%s) (%d %d %d) simpleGrading (1 1 1)
"%(" ".join(map(str,v)),a,b,c)
    d += ");

edges
(
"
    for a,b,m in arcs: d += "    arc %d %d (%.8g %.8g %.8g)
"%(a,b,m[0],m[1], 0.0 if a<10 else THK)
    d += ");

boundary
(
"
    for name,fs in patches.items():
        d += "    %s
    {
        type %s;
        faces
        (
"%(name,ptype[name])
        for f in fs: d += "            (%s)
"%" ".join(map(str,f))
        d += "        );
    }
"
    d += ");

mergePatchPairs ();
"
    open(path,"w").write(d)

